// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;

import org.junit.jupiter.api.Test;

class LmdbAdjacencyPlaneStatisticsTest {

	@Test
	void oneHundredFiftyThousandUpdatesUseBoundedExactSummaryLevels() {
		int predicates = 37;
		long[][] expected = new long[predicates][LmdbAdjacencyPlane.PLANE_COUNT];
		LmdbAdjacencyPlaneStatistics statistics = LmdbAdjacencyPlaneStatistics.empty();
		for (int update = 0; update < 150_000; update++) {
			int predicateOrdinal = update % predicates;
			int plane = update % LmdbAdjacencyPlane.PLANE_COUNT;
			LmdbAdjacencyPlaneStatistics.UpdateBuilder builder = new LmdbAdjacencyPlaneStatistics.UpdateBuilder();
			builder.add(uri(predicateOrdinal + 1), plane, 1, 1);
			statistics = statistics.with(builder.build());
			expected[predicateOrdinal][plane]++;
		}

		assertThat(statistics.summaryLevelCount()).isLessThanOrEqualTo(64);
		for (int predicate = 0; predicate < predicates; predicate++) {
			for (int plane = 0; plane < LmdbAdjacencyPlane.PLANE_COUNT; plane++) {
				assertThat(statistics.quadCount(uri(predicate + 1), plane)).isEqualTo(expected[predicate][plane]);
				assertThat(statistics.keyCount(uri(predicate + 1), plane)).isEqualTo(expected[predicate][plane]);
			}
		}

		LmdbAdjacencyPlaneStatistics.UpdateBuilder remove = new LmdbAdjacencyPlaneStatistics.UpdateBuilder();
		for (int predicate = 0; predicate < predicates; predicate++) {
			for (int plane = 0; plane < LmdbAdjacencyPlane.PLANE_COUNT; plane++) {
				remove.add(uri(predicate + 1), plane, -expected[predicate][plane], -expected[predicate][plane]);
			}
		}
		statistics = statistics.with(remove.build());
		for (int predicate = 0; predicate < predicates; predicate++) {
			for (int plane = 0; plane < LmdbAdjacencyPlane.PLANE_COUNT; plane++) {
				assertThat(statistics.quadCount(uri(predicate + 1), plane)).isZero();
				assertThat(statistics.keyCount(uri(predicate + 1), plane)).isZero();
			}
		}
	}

	@Test
	void cancellingPredicateChurnIsElidedExactly() {
		long predicate = uri(1);
		LmdbAdjacencyPlaneStatistics statistics = LmdbAdjacencyPlaneStatistics.empty();
		for (int update = 0; update < 150_000; update++) {
			long delta = (update & 1) == 0 ? 1 : -1;
			LmdbAdjacencyPlaneStatistics.UpdateBuilder builder = new LmdbAdjacencyPlaneStatistics.UpdateBuilder();
			builder.add(predicate, LmdbAdjacencyPlane.PLANE_INCOMING_EXPLICIT, delta, delta);
			statistics = statistics.with(builder.build());
		}

		assertThat(statistics.quadCount(predicate, LmdbAdjacencyPlane.PLANE_INCOMING_EXPLICIT)).isZero();
		assertThat(statistics.keyCount(predicate, LmdbAdjacencyPlane.PLANE_INCOMING_EXPLICIT)).isZero();
		assertThat(statistics.summaryLevelCount()).isZero();
	}

	private static long uri(long payload) {
		return ValueIds.createId(ValueIds.T_URI, payload);
	}
}
